constexpr int kRate = 8000;
constexpr int kDuration = 24;
constexpr double kOrigin = 0.2137;

std::vector<CSAMPLE> pulses(
        int rate = kRate, int duration = kDuration, double start = kOrigin, double bpm = 120) {
    std::vector<CSAMPLE> audio(static_cast<std::size_t>(rate) * duration * 2);
    for (int beat = 0; start + beat * 60 / bpm < duration; ++beat) {
        const auto first = static_cast<std::size_t>(std::llround((start + beat * 60 / bpm) * rate));
        for (int frame = 0; frame < rate / 40 && first + frame < audio.size() / 2; ++frame) {
            const double time = static_cast<double>(frame) / rate;
            const auto value = static_cast<CSAMPLE>(
                    0.8 * std::exp(-100 * time) * std::cos(2 * M_PI * 100 * time));
            audio[(first + frame) * 2] = value;
            audio[(first + frame) * 2 + 1] = value;
        }
    }
    return audio;
}

bool feed(AnalyzerBeats* analyzer, const std::vector<CSAMPLE>& samples, int channels = 2) {
    const std::size_t chunk = 997 * channels;
    for (std::size_t offset = 0; offset < samples.size(); offset += chunk) {
        if (!analyzer->processSamples(samples.data() + offset,
                    static_cast<SINT>(std::min(chunk, samples.size() - offset)))) {
            return false;
        }
    }
    return true;
}

mixxx::BeatsPointer directGrid(const std::vector<CSAMPLE>& audio, int rate = kRate) {
    mixxx::AnalyzerPhaseGrid plugin;
    if (!plugin.initialize(mixxx::audio::SampleRate(rate)) ||
            !plugin.processSamples(audio.data(), static_cast<SINT>(audio.size())) ||
            !plugin.finalize()) {
        return {};
    }
    return plugin.resolvedBeatGrid(QStringLiteral("test"));
}

class PhaseGridAnalyzerTest : public MixxxTest {
  protected:
    void select() {
        BeatDetectionSettings(config()).setBeatPluginId(
                mixxx::AnalyzerPhaseGrid::pluginInfo().id());
    }

    TrackPointer track(int duration = kDuration,
            int rate = kRate,
            mixxx::audio::ChannelCount channels = mixxx::audio::ChannelCount::stereo()) {
        auto result = Track::newTemporary();
        result->setAudioProperties(channels,
                mixxx::audio::SampleRate(rate),
                mixxx::audio::Bitrate(),
                mixxx::Duration::fromSeconds(duration));
        return result;
    }

    bool initialize(AnalyzerBeats* analyzer, const TrackPointer& pTrack) {
        return analyzer->initialize(AnalyzerTrack(pTrack),
                pTrack->getSampleRate(),
                pTrack->getChannels(),
                static_cast<SINT>(pTrack->getDuration() * pTrack->getSampleRate()));
    }
};

TEST(PhaseGridPluginTest, AppendsSelectableExperimentalAnalyzerAndKeepsLegacyDefaults) {
    const auto plugins = AnalyzerBeats::availablePlugins();
    ASSERT_EQ(3, plugins.size());
    EXPECT_EQ(mixxx::AnalyzerQueenMaryBeats::pluginInfo().id(), plugins[0].id());
    EXPECT_EQ(mixxx::AnalyzerSoundTouchBeats::pluginInfo().id(), plugins[1].id());
    EXPECT_EQ(QStringLiteral("phase-histogram:1"), plugins[2].id());
    EXPECT_EQ(plugins[0].id(), AnalyzerBeats::defaultPlugin().id());
    EXPECT_TRUE(plugins[2].name().contains(QStringLiteral("Experimental")));
    EXPECT_FALSE(plugins[2].isConstantTempoSupported());
    EXPECT_FALSE(mixxx::AnalyzerQueenMaryBeats().providesResolvedBeatGrid());
    EXPECT_FALSE(mixxx::AnalyzerSoundTouchBeats().providesResolvedBeatGrid());
}

TEST(PhaseGridPluginTest, ReinitializationAndSilenceNeverReuseAnEarlierResult) {
    const auto audio = pulses();
    mixxx::AnalyzerPhaseGrid plugin;
    EXPECT_FALSE(plugin.resolvedBeatGrid(QString()));
    ASSERT_TRUE(plugin.initialize(mixxx::audio::SampleRate(kRate)));
    ASSERT_TRUE(plugin.processSamples(audio.data(), static_cast<SINT>(audio.size())));
    ASSERT_TRUE(plugin.finalize());
    ASSERT_TRUE(plugin.resolvedBeatGrid(QString()));
    EXPECT_TRUE(plugin.diagnostics().value(QStringLiteral("accepted")).toBool());
    EXPECT_FALSE(plugin.diagnostics().value(QStringLiteral("original_equivalence")).toBool());
    EXPECT_FALSE(plugin.finalize());
    ASSERT_TRUE(plugin.initialize(mixxx::audio::SampleRate(kRate)));
    EXPECT_FALSE(plugin.resolvedBeatGrid(QString()));
    EXPECT_EQ(0, plugin.diagnostics().value(QStringLiteral("processed_frames")).toDouble());
    const std::vector<CSAMPLE> silence(audio.size());
    ASSERT_TRUE(plugin.processSamples(silence.data(), static_cast<SINT>(silence.size())));
    EXPECT_FALSE(plugin.finalize());
    EXPECT_FALSE(plugin.resolvedBeatGrid(QString()));
}

TEST(PhaseGridPluginTest, InvalidInputPoisonsTheRunAndNeverExposesAPartialGrid) {
    for (int variant = 0; variant < 5; ++variant) {
        SCOPED_TRACE(variant);
        mixxx::AnalyzerPhaseGrid plugin;
        ASSERT_TRUE(plugin.initialize(mixxx::audio::SampleRate(kRate)));
        CSAMPLE input[2] = {0, 0};
        if (variant == 3) {
            input[0] = util_float_nan();
        } else if (variant == 4) {
            input[1] = util_float_infinity();
        }
        EXPECT_FALSE(plugin.processSamples(variant == 0 ? nullptr : input,
                variant == 1           ? 1
                        : variant == 2 ? -2
                                       : 2));
        EXPECT_FALSE(plugin.finalize());
        EXPECT_FALSE(plugin.resolvedBeatGrid(QString()));
        EXPECT_FALSE(plugin.processSamples(input, 0));
    }
    mixxx::AnalyzerPhaseGrid plugin;
    EXPECT_FALSE(plugin.initialize(mixxx::audio::SampleRate()));
    EXPECT_FALSE(plugin.initialize(mixxx::audio::SampleRate(500)));
    EXPECT_FALSE(plugin.initialize(mixxx::audio::SampleRate(384001)));
    ASSERT_TRUE(plugin.initialize(mixxx::audio::SampleRate(kRate)));
    EXPECT_TRUE(plugin.processSamples(nullptr, 0));
    EXPECT_FALSE(plugin.finalize());
}

TEST(PhaseGridPluginTest, MetadataFingerprintsNativeFrontendAndExperimentalCoreConfiguration) {
    const auto version = mixxx::AnalyzerPhaseGrid::extraVersionInfo(
            mixxx::audio::SampleRate(kRate), mixxx::audio::ChannelCount::stereo());
    EXPECT_EQ(QStringLiteral("proposed-count-only-v1"),
            version.value(QStringLiteral("phase_grid_policy")));
    EXPECT_EQ(QStringLiteral("decompiled-radius-one-shifted-v1"),
            version.value(QStringLiteral("phase_grid_search")));
    EXPECT_EQ(64, version.value(QStringLiteral("phase_grid_config")).size());
    EXPECT_NE(version,
            mixxx::AnalyzerPhaseGrid::extraVersionInfo(
                    mixxx::audio::SampleRate(48000), mixxx::audio::ChannelCount::stereo()));
    EXPECT_NE(version,
            mixxx::AnalyzerPhaseGrid::extraVersionInfo(
                    mixxx::audio::SampleRate(kRate), mixxx::audio::ChannelCount::mono()));
}

TEST_F(PhaseGridAnalyzerTest, StoresExactResolvedCorePhaseAndUsesConstantCacheForAllGlobalModes) {
    select();
    const auto audio = pulses(44100);
    const auto expected = directGrid(audio, 44100);
    ASSERT_TRUE(expected);
    EXPECT_GT(expected->firstBeat().value(), 0);
    BeatDetectionSettings settings(config());
    settings.setFastAnalysis(true);
    settings.setReanalyzeWhenSettingsChange(true);
    for (const auto mode : {mixxx::BeatGridMode::Auto,
                 mixxx::BeatGridMode::Variable,
                 mixxx::BeatGridMode::Constant}) {
        SCOPED_TRACE(static_cast<int>(mode));
        settings.setTempoMode(mode);
        const auto pTrack = track(kDuration, 44100);
        AnalyzerBeats analyzer(config());
        ASSERT_TRUE(initialize(&analyzer, pTrack));
        ASSERT_TRUE(feed(&analyzer, audio));
        analyzer.storeResults(pTrack);
        analyzer.cleanup();
        const auto actual = pTrack->getBeats();
        ASSERT_TRUE(actual);
        EXPECT_TRUE(actual->hasConstantTempo());
        EXPECT_DOUBLE_EQ(expected->getBpmInRange(mixxx::audio::kStartFramePos,
                                         mixxx::audio::FramePos(44100 * kDuration))
                                 .value(),
                pTrack->getBpm());
        EXPECT_EQ(expected->firstBeat(), actual->firstBeat());
        EXPECT_EQ(mode, settings.getTempoMode());
        EXPECT_TRUE(settings.getFastAnalysis());
        EXPECT_TRUE(actual->getSubVersion().contains(QStringLiteral("phase_grid_config=")));
        EXPECT_FALSE(actual->getSubVersion().contains(QStringLiteral("fast_analysis")));
        EXPECT_FALSE(actual->getSubVersion().contains(QStringLiteral("audio_grid_evidence")));
        settings.setTempoMode(mode == mixxx::BeatGridMode::Auto ? mixxx::BeatGridMode::Variable
                                                                : mixxx::BeatGridMode::Auto);
        EXPECT_FALSE(initialize(&analyzer, pTrack));
    }
}

