TEST_F(PhaseGridAnalyzerTest, StemUsesTheExistingRhythmicChannelPolicyAndCacheKey) {
    select();
    BeatDetectionSettings settings(config());
    settings.setStemStrategy(BeatDetectionSettings::StemStrategy::Enforced);
    settings.setReanalyzeWhenSettingsChange(true);
    const auto stereo = pulses();
    const auto expected = directGrid(stereo);
    ASSERT_TRUE(expected);
    std::vector<CSAMPLE> stem(stereo.size() * 4);
    for (std::size_t frame = 0; frame < stereo.size() / 2; ++frame) {
        stem[frame * 8] = stereo[frame * 2];
        stem[frame * 8 + 1] = stereo[frame * 2 + 1];
    }
    const auto pTrack = track(kDuration, kRate, mixxx::audio::ChannelCount::stem());
    AnalyzerBeats analyzer(config());
    ASSERT_TRUE(initialize(&analyzer, pTrack));
    ASSERT_TRUE(feed(&analyzer, stem, 8));
    analyzer.storeResults(pTrack);
    analyzer.cleanup();
    ASSERT_TRUE(pTrack->getBeats());
    EXPECT_EQ(expected->firstBeat(), pTrack->getBeats()->firstBeat());
    EXPECT_TRUE(pTrack->getBeats()->getSubVersion().contains(
            QStringLiteral("phase_grid_stem_strategy=2")));
    EXPECT_FALSE(initialize(&analyzer, pTrack));
    settings.setStemStrategy(BeatDetectionSettings::StemStrategy::Disabled);
    EXPECT_TRUE(initialize(&analyzer, pTrack));
    analyzer.cleanup();
}

TEST_F(PhaseGridAnalyzerTest, ManualImportedAndLockedGridsAreProtected) {
    select();
    const auto pTrack = track();
    const auto old = mixxx::Beats::fromConstTempo(
            pTrack->getSampleRate(), mixxx::audio::kStartFramePos, mixxx::Bpm(87));
    pTrack->trySetBeats(old);
    AnalyzerBeats analyzer(config(), true);
    EXPECT_FALSE(initialize(&analyzer, pTrack));
    EXPECT_EQ(old, pTrack->getBeats());
    BeatDetectionSettings settings(config());
    settings.setReanalyzeWhenSettingsChange(true);
    pTrack->setBpmLocked(true);
    EXPECT_FALSE(initialize(&analyzer, pTrack));
    pTrack->setBpmLocked(false);
    const auto imported = mixxx::Beats::fromConstTempo(pTrack->getSampleRate(),
            mixxx::audio::FramePos(1000),
            mixxx::Bpm(87),
            mixxx::rekordboxconstants::beatsSubversion);
    pTrack->trySetBeats(imported);
    EXPECT_FALSE(initialize(&analyzer, pTrack));
    EXPECT_EQ(imported, pTrack->getBeats());
}

TEST_F(PhaseGridAnalyzerTest, LateLockSilenceAndMalformedFramesDoNotOverwriteExistingBeats) {
    select();
    BeatDetectionSettings(config()).setReanalyzeWhenSettingsChange(true);
    for (int failure = 0; failure < 4; ++failure) {
        SCOPED_TRACE(failure);
        const auto pTrack = track(failure == 3 ? kDuration * 2 : kDuration);
        const auto old = mixxx::Beats::fromConstTempo(pTrack->getSampleRate(),
                mixxx::audio::FramePos(1000),
                mixxx::Bpm(87),
                QStringLiteral("previous-analysis"));
        pTrack->trySetBeats(old);
        AnalyzerBeats analyzer(config());
        ASSERT_TRUE(initialize(&analyzer, pTrack));
        auto audio = pulses();
        if (failure == 0) {
            std::fill(audio.begin(), audio.end(), 0);
        }
        ASSERT_TRUE(feed(&analyzer, audio));
        if (failure == 1) {
            EXPECT_FALSE(analyzer.processSamples(audio.data(), 1));
        } else if (failure == 2) {
            pTrack->setBpmLocked(true);
        }
        analyzer.storeResults(pTrack);
        analyzer.cleanup();
        EXPECT_EQ(old, pTrack->getBeats());
    }
}

