TEST_F(PhaseGridAnalyzerTest, NonFiniteInputIsRejectedBeforeMonoOrStemConversion) {
    select();
    BeatDetectionSettings settings(config());
    settings.setReanalyzeWhenSettingsChange(true);
    settings.setStemStrategy(BeatDetectionSettings::StemStrategy::Enforced);
    for (const int channels : {1, 2, 8}) {
        for (const CSAMPLE invalid :
                {util_float_nan(), util_float_infinity(), -util_float_infinity()}) {
            SCOPED_TRACE(channels);
            const auto pTrack = track(kDuration, kRate, mixxx::audio::ChannelCount(channels));
            const auto old = mixxx::Beats::fromConstTempo(pTrack->getSampleRate(),
                    mixxx::audio::FramePos(1000),
                    mixxx::Bpm(87),
                    QStringLiteral("previous-analysis"));
            pTrack->trySetBeats(old);
            AnalyzerBeats analyzer(config());
            ASSERT_TRUE(initialize(&analyzer, pTrack));
            CSAMPLE input[8] = {};
            input[channels - 1] = invalid;
            EXPECT_FALSE(analyzer.processSamples(input, channels));
            EXPECT_FALSE(analyzer.processSamples(nullptr, 0));
            analyzer.storeResults(pTrack);
            analyzer.cleanup();
            EXPECT_EQ(old, pTrack->getBeats());
        }
    }
}

